        "active_step": {
          "anyOf": [
            {
              "$ref": "common.schema.json#/$defs/Id"
            },
            {
              "type": "null"
            }
          ]
        },
        "pause_requested": {
          "type": "boolean"
        },
        "cancel_requested": {
          "type": "boolean"
        },
        "resume_to": {
          "anyOf": [
            {
              "$ref": "common.schema.json#/$defs/RunState"
            },
            {
              "type": "null"
            }
          ]
        },
        "retry_of": {
          "anyOf": [
            {
              "$ref": "common.schema.json#/$defs/Id"
            },
            {
              "type": "null"
            }
          ]
        },
        "error": {
          "anyOf": [
            {
              "$ref": "#/$defs/Failure"
            },
            {
              "type": "null"
            }
          ]
        },
        "created_at": {
          "$ref": "common.schema.json#/$defs/Timestamp"
        },
        "updated_at": {
          "$ref": "common.schema.json#/$defs/Timestamp"
        },
        "verification_report": {
          "anyOf": [
            {
              "$ref": "#/$defs/VerificationReport"
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "required": [
        "contract_version",
        "schema_version",
        "run_id",
        "snapshot_hash",
        "title",
        "state",
        "source_version",
        "state_sequence",
        "modes",
        "definition_snapshot",
        "plan",
        "plan_hash",
        "proposal",
        "proposal_history",
        "approval",
        "permission_snapshot",
        "messages",
        "summary_records",
        "steps",
        "required_checks",
        "artifacts",
        "manifest",
        "operations",
        "usage",
        "workspace",
        "workflow_checkpoint",
        "history",
        "active_step",
        "pause_requested",
        "cancel_requested",
        "resume_to",
        "retry_of",
        "error",
        "created_at",
        "updated_at",
        "verification_report"
      ],
      "allOf": [
        {
          "if": {
            "properties": {
              "modes": {
                "properties": {
                  "execution_mode": {
                    "const": "local"
                  }
                },
                "required": [
                  "execution_mode"
                ]
              }
            },
            "required": [
              "modes"
            ]
          },
          "then": {
            "properties": {
              "workflow_checkpoint": {
                "type": "null"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "state": {
                "const": "PLAN"
              }
            },
            "required": [
              "state"
            ]
          },
          "then": {
            "properties": {
              "plan": {
                "$ref": "#/$defs/ProjectPlan"
              },
              "proposal": {
                "$ref": "#/$defs/Proposal"
              },
              "plan_hash": {
                "$ref": "common.schema.json#/$defs/Hash"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "state": {
                "const": "DONE"
              }
            },
            "required": [
              "state"
            ]
          },
          "then": {
            "properties": {
              "manifest": {
                "$ref": "#/$defs/ArtifactManifest"
              },
              "approval": {
                "$ref": "#/$defs/Approval"
              },
              "error": {
                "type": "null"
              },
              "verification_report": {
                "allOf": [
                  {
                    "$ref": "#/$defs/VerificationReport"
                  },
                  {
                    "properties": {
                      "outcome": {
                        "const": "passed"
                      }
                    }
                  }
                ]
              }
            }
          }
        }
      ]
    },
    "VerificationReport": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "contract_version": {
          "const": "1.0.0"
        },
        "report_id": {
          "$ref": "common.schema.json#/$defs/Id"
        },
        "report_version": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "run_id": {
          "$ref": "common.schema.json#/$defs/Id"
        },
        "source_version": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "definition_snapshot_hash": {
          "$ref": "common.schema.json#/$defs/Hash"
        },
        "proposal_snapshot_hash": {
          "$ref": "common.schema.json#/$defs/Hash"
        },
        "manifest_ref": {
          "$ref": "#/$defs/ObjectReference"
        },
        "checks": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/RequiredCheck"
          },
          "minItems": 1,
          "maxItems": 32
        },
        "outcome": {
          "enum": [
            "not_ready",
            "passed",
            "failed"
          ]
        },
        "report_hash": {
          "$ref": "common.schema.json#/$defs/Hash"
        },
        "created_at": {
          "$ref": "common.schema.json#/$defs/Timestamp"
        }
      },
      "required": [
        "contract_version",
        "report_id",
        "report_version",
        "run_id",
        "source_version",
        "definition_snapshot_hash",
        "proposal_snapshot_hash",
        "manifest_ref",
        "checks",
        "outcome",
        "report_hash",
        "created_at"
      ],
      "allOf": [
        {
          "properties": {
            "manifest_ref": {
              "properties": {
                "object_type": {
                  "const": "manifest"
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "outcome": {
                "const": "passed"
              }
            },
            "required": [
              "outcome"
            ]
          },
          "then": {
            "properties": {
              "checks": {
                "items": {
                  "properties": {
                    "status": {
                      "const": "passed"
                    }
                  }
                }
              }
            }
          }
        }
      ]
    },
    "DefinitionSelection": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "definition_id": {
          "$ref": "common.schema.json#/$defs/Id"
        },
        "definition_version": {
          "type": "string",
          "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+(?:-[A-Za-z0-9.-]+)?$",
          "maxLength": 64
        },
        "definition_hash": {
          "$ref": "common.schema.json#/$defs/Hash"
        }
      },
      "required": [
        "definition_id",
        "definition_version",
        "definition_hash"
      ]
    },
    "CreateRunRequest": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "contract_version": {
          "const": "1.0.0"
        },
        "schema_version": {
          "const": 2
        },
        "command_id": {
          "$ref": "common.schema.json#/$defs/Id"
        },
        "run_id": {
          "$ref": "common.schema.json#/$defs/Id"
        },
        "title": {
          "type": "string",
          "minLength": 1,
          "maxLength": 4096
        },
        "modes": {
          "$ref": "common.schema.json#/$defs/Modes"
        },
        "definition_selection": {
          "$ref": "#/$defs/DefinitionSelection"
        },
        "initial_content": {
          "type": "string",
          "minLength": 1,
          "maxLength": 16000
        }
      },
      "required": [
        "contract_version",
        "schema_version",
        "command_id",
        "run_id",
        "title",
        "modes",
        "definition_selection",
        "initial_content"
      ]
    },
    "MessageRequest": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "contract_version": {
          "const": "1.0.0"
        },
        "schema_version": {
          "const": 2
        },
        "command_id": {
          "$ref": "common.schema.json#/$defs/Id"
        },
        "target": {
          "allOf": [
            {
              "$ref": "message.schema.json#/$defs/ObjectRef"
            },
            {
              "properties": {
                "object_type": {
                  "const": "run"
                }
              }
            }
          ]
        },
        "content": {
          "type": "string",
          "minLength": 1,
          "maxLength": 16000
        }
      },
      "required": [
        "contract_version",
        "schema_version",
        "command_id",
        "target",
        "content"
      ]
    },
    "ControlRequest": {
      "$ref": "message.schema.json#/$defs/ActionIntent"
    },
    "CommandReceipt": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "contract_version": {
          "const": "1.0.0"
        },
        "schema_version": {
          "const": 2
        },
        "command_id": {
          "$ref": "common.schema.json#/$defs/Id"
        },
        "run_id": {
          "$ref": "common.schema.json#/$defs/Id"
        },
        "command_fingerprint": {
          "$ref": "common.schema.json#/$defs/Hash"
        },
        "status": {
          "enum": [
            "accepted",
            "queued",
            "processed",
            "rejected",
            "result_unknown"
          ]
        },
        "run_ref": {
          "anyOf": [
            {
              "allOf": [
                {
                  "$ref": "message.schema.json#/$defs/ObjectRef"
                },
                {
                  "properties": {
                    "object_type": {
                      "const": "run"
                    }
                  }
                }
              ]
            },
            {
              "type": "null"
            }
          ]
        },
        "result_refs": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/ObjectReference"
          },
          "minItems": 0,
          "maxItems": 32
        },
        "error": {
          "anyOf": [
            {
              "$ref": "#/$defs/Failure"
            },
            {
              "type": "null"
            }
          ]
        },
        "accepted_at": {
          "$ref": "common.schema.json#/$defs/Timestamp"
        },
        "updated_at": {
          "$ref": "common.schema.json#/$defs/Timestamp"
        }
      },
      "required": [
        "contract_version",
        "schema_version",
        "command_id",
        "run_id",
        "command_fingerprint",
        "status",
        "run_ref",
        "result_refs",
        "error",
        "accepted_at",
        "updated_at"
      ],
      "allOf": [
        {
          "if": {
            "properties": {
              "status": {
                "const": "rejected"
              }
            },
            "required": [
              "status"
            ]
          },
          "then": {
            "properties": {
              "error": {
                "$ref": "#/$defs/Failure"
              }
            }
          },
          "else": {
            "properties": {
              "error": {
                "type": "null"
              }
            }
          }
        }
      ]
    },
    "SnapshotEvent": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "contract_version": {
          "const": "1.0.0"
        },
        "schema_version": {
          "const": 2
        },
        "event_id": {
          "$ref": "common.schema.json#/$defs/Id"
        },
        "run_id": {
          "$ref": "common.schema.json#/$defs/Id"
        },
        "source_version": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "state_sequence": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "run_ref": {
          "allOf": [
            {
              "$ref": "message.schema.json#/$defs/ObjectRef"
            },
            {
              "properties": {
                "object_type": {
                  "const": "run"
                }
              }
            }
          ]
        },
        "occurred_at": {
          "$ref": "common.schema.json#/$defs/Timestamp"
        }
      },
      "required": [
        "contract_version",
        "schema_version",
        "event_id",
        "run_id",
        "source_version",
        "state_sequence",
        "run_ref",
        "occurred_at"
      ]
    },
    "ErrorResponse": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "error": {
          "type": "string",
          "minLength": 1,
          "maxLength": 4096
        },
        "code": {
          "$ref": "common.schema.json#/$defs/Id"
        },
        "legacy_read_url": {
          "type": "string",
          "pattern": "^/api/runs/[A-Za-z0-9][A-Za-z0-9._:-]*$",
          "maxLength": 160
        }
      },
      "required": [
        "error",
        "code"
      ],
      "allOf": [
        {
          "if": {
            "properties": {
              "code": {
                "const": "legacy_contract_incomplete"
              }
            },
            "required": [
              "code"
            ]
          },
          "then": {
            "required": [
              "legacy_read_url"
            ]
          },
          "else": {
            "not": {
              "required": [
                "legacy_read_url"
              ]
            }
          }
        }
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://agentstudio.invalid/contracts/1.0.0/common.schema.json",
  "title": "项目创建 Agent 公共字段契约 1.0.0",
  "$comment": "目标规范；.invalid 是稳定标识，不是运行时下载地址。所有引用离线登记。",
  "$defs": {
    "Id": {"type": "string", "minLength": 1, "maxLength": 128, "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]*$"},
    "Hash": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "Timestamp": {"type": "string", "format": "date-time", "pattern": "Z$"},
    "RunState": {"enum": ["INTAKE", "CLARIFY", "PLAN", "IMPLEMENT", "VERIFY", "DELIVER", "DONE", "PAUSED", "BLOCKED", "FAILED", "CANCELLED"]},
    "ExecutionMode": {"enum": ["temporal", "local"]},
    "DecisionMode": {"enum": ["model", "rules"]},
    "DeliveryMode": {"enum": ["gitlab", "local"]},
    "Modes": {
      "type": "object", "additionalProperties": false,
      "required": ["execution_mode", "decision_mode", "delivery_mode"],
      "properties": {
        "execution_mode": {"$ref": "#/$defs/ExecutionMode"},
        "decision_mode": {"$ref": "#/$defs/DecisionMode"},
        "delivery_mode": {"$ref": "#/$defs/DeliveryMode"}
      }
    },
    "PositiveVersion": {"type": "integer", "minimum": 1, "maximum": 9007199254740991},
    "RelativePath": {"type": "string", "minLength": 1, "maxLength": 512, "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$))(?!.*\\\\)[A-Za-z0-9._/-]+$"},
    "ObjectRef": {
      "type": "object", "additionalProperties": false,
      "required": ["object_type", "object_id", "object_version", "source_version", "hash"],
      "properties": {
        "object_type": {"enum": ["run", "message", "proposal", "definition", "plan", "manifest", "verification_report", "artifact", "summary", "skill", "schema", "template", "approval", "decision", "validation", "execution", "evidence", "workspace"]},
        "object_id": {"$ref": "#/$defs/Id"},
        "object_version": {"$ref": "#/$defs/PositiveVersion"},
        "source_version": {"$ref": "#/$defs/PositiveVersion"},
        "hash": {"$ref": "#/$defs/Hash"}
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://agentstudio.invalid/contracts/1.0.0/message.schema.json",
  "title": "Project Agent canonical message protocol",
  "description": "Target v2 contract. Current legacy /api DTOs do not satisfy this schema. Compatibility readers must not promote adapted history into executable messages.",
  "$ref": "#/$defs/MessageEnvelope",
  "$defs": {
    "MessageEnvelope": {
      "type": "object",
      "additionalProperties": false,
      "required": ["schema_version", "contract_version", "run_id", "message_id", "sequence", "source_version", "state_sequence", "role", "created_at", "modes", "parts"],
      "properties": {
        "schema_version": {"const": 2},
        "contract_version": {"const": "1.0.0"},
        "run_id": {"$ref": "common.schema.json#/$defs/Id"},
        "message_id": {"$ref": "common.schema.json#/$defs/Id"},
        "sequence": {"$ref": "common.schema.json#/$defs/PositiveVersion"},
        "source_version": {"$ref": "common.schema.json#/$defs/PositiveVersion"},
        "state_sequence": {"$ref": "common.schema.json#/$defs/PositiveVersion"},
        "role": {"enum": ["user", "assistant", "system", "tool"]},
        "created_at": {"$ref": "common.schema.json#/$defs/Timestamp"},
        "modes": {"$ref": "common.schema.json#/$defs/Modes"},
        "reply_to_message_id": {"$ref": "common.schema.json#/$defs/Id"},
        "command_id": {"$ref": "common.schema.json#/$defs/Id"},
        "parts": {"type": "array", "minItems": 1, "maxItems": 64, "items": {"$ref": "#/$defs/Part"}}
      }
    },
    "ObjectRef": {
      "allOf": [{"$ref": "common.schema.json#/$defs/ObjectRef"}],
      "properties": {
        "object_type": {"enum": ["run", "message", "proposal", "definition", "plan", "manifest", "verification_report", "artifact", "summary"]}
      }
    },
    "Part": {
      "oneOf": [
        {"$ref": "#/$defs/TextPart"},
        {"$ref": "#/$defs/ComponentPart"},
        {"$ref": "#/$defs/DiffPart"},
        {"$ref": "#/$defs/ChoicePart"},
        {"$ref": "#/$defs/ActionPart"}
      ]
    },
    "PartBase": {
      "type": "object",
      "required": ["part_id", "part_version", "type", "fallback_text"],
      "properties": {
        "part_id": {"$ref": "common.schema.json#/$defs/Id"},
        "part_version": {"const": 1},
        "type": {"type": "string"},
        "fallback_text": {"type": "string", "maxLength": 4096}
      }
    },
    "TextPart": {
      "allOf": [{"$ref": "#/$defs/PartBase"}],
      "unevaluatedProperties": false,
      "required": ["text", "format"],
      "properties": {
        "type": {"const": "text"},
        "text": {"type": "string", "maxLength": 65536},
        "format": {"enum": ["plain", "markdown"]}
      }
    },
    "ComponentPart": {
      "allOf": [{"$ref": "#/$defs/PartBase"}],
      "unevaluatedProperties": false,
      "required": ["component_id", "component_version", "component_type", "component_schema", "payload"],
      "properties": {
        "type": {"const": "component"},
        "component_id": {"$ref": "common.schema.json#/$defs/Id"},
        "component_version": {"$ref": "common.schema.json#/$defs/PositiveVersion"},
        "component_type": {"type": "string", "pattern": "^[a-z][a-z0-9_]{0,63}$"},
        "component_schema": {"type": "string", "maxLength": 160},
        "payload": true
      },
      "oneOf": [
        {
          "properties": {
            "component_type": {"const": "clarification"},
            "component_schema": {"const": "urn:agentstudio:component:clarification:1.0.0"},
            "payload": {"$ref": "#/$defs/ClarificationPayload"}
          }
        },
        {
          "properties": {
            "component_type": {"const": "proposal_diff"},
            "component_schema": {"const": "urn:agentstudio:component:proposal_diff:1.0.0"},
            "payload": {"$ref": "#/$defs/ProposalDiffPayload"}
          }
        },
        {
          "properties": {
            "component_type": {"const": "progress"},
            "component_schema": {"const": "urn:agentstudio:component:progress:1.0.0"},
            "payload": {"$ref": "#/$defs/ProgressPayload"}
          }
        },
        {
          "properties": {
            "component_type": {"const": "artifact_manifest"},
            "component_schema": {"const": "urn:agentstudio:component:artifact_manifest:1.0.0"},
            "payload": {"$ref": "#/$defs/ArtifactManifestPayload"}
          }
        },
        {
          "properties": {
            "component_type": {"const": "verification_report"},
            "component_schema": {"const": "urn:agentstudio:component:verification_report:1.0.0"},
            "payload": {"$ref": "#/$defs/VerificationReportPayload"}
          }
        },
        {
          "properties": {
            "component_type": {"not": {"enum": ["clarification", "proposal_diff", "progress", "artifact_manifest", "verification_report"]}},
            "component_schema": {"type": "string", "pattern": "^urn:agentstudio:component:[a-z][a-z0-9_]{0,63}:[0-9]+\\.[0-9]+\\.[0-9]+$"},
            "payload": {"$ref": "#/$defs/JsonValue"}
          }
        }
      ]
    },
    "ClarificationPayload": {
      "type": "object",
      "additionalProperties": false,
      "required": ["question", "field_ids"],
      "properties": {
        "question": {"type": "string", "minLength": 1, "maxLength": 4096},
        "field_ids": {"type": "array", "maxItems": 32, "uniqueItems": true, "items": {"$ref": "common.schema.json#/$defs/Id"}}
      }
    },
    "ProposalDiffPayload": {
      "type": "object",
      "additionalProperties": false,
      "required": ["proposal_ref", "summary", "changed_paths"],
      "properties": {
        "proposal_ref": {"allOf": [{"$ref": "#/$defs/ObjectRef"}, {"properties": {"object_type": {"const": "proposal"}}}]},
        "summary": {"type": "string", "maxLength": 4096},
        "changed_paths": {"type": "array", "maxItems": 128, "uniqueItems": true, "items": {"$ref": "#/$defs/RelativePath"}}
      }
    },
    "ProgressPayload": {
      "type": "object",
      "additionalProperties": false,
      "required": ["state", "summary"],
      "properties": {
        "state": {"$ref": "common.schema.json#/$defs/RunState"},
        "summary": {"type": "string", "maxLength": 4096},
        "delivery_step": {"enum": ["remote_repo", "remote_ci", "package"]}
      },
      "allOf": [{"if": {"required": ["delivery_step"]}, "then": {"properties": {"state": {"const": "DELIVER"}}}}]
    },
    "ArtifactManifestPayload": {
      "type": "object",
      "additionalProperties": false,
      "required": ["manifest_ref", "artifact_count", "summary"],
      "properties": {
        "manifest_ref": {"allOf": [{"$ref": "#/$defs/ObjectRef"}, {"properties": {"object_type": {"const": "manifest"}}}]},
        "artifact_count": {"type": "integer", "minimum": 0, "maximum": 128},
        "summary": {"type": "string", "maxLength": 4096}
      }
    },
    "VerificationReportPayload": {
      "type": "object",
      "additionalProperties": false,
      "required": ["report_ref", "result", "summary"],
      "properties": {
        "report_ref": {"allOf": [{"$ref": "#/$defs/ObjectRef"}, {"properties": {"object_type": {"const": "verification_report"}}}]},
        "result": {"enum": ["not_ready", "passed", "failed"]},
        "summary": {"type": "string", "maxLength": 4096}
      }
    },
    "DiffPart": {
      "allOf": [{"$ref": "#/$defs/PartBase"}],
      "unevaluatedProperties": false,
      "required": ["object_ref", "summary", "changes"],
      "properties": {
        "type": {"const": "diff"},
        "object_ref": {"$ref": "#/$defs/ObjectRef"},
